72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    /**
78	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
79	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
80	     */
81	    private static final Pattern EMAIL_PATTERN =
82	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
83	
84	    /**
85	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
86	     * line here so audit trails can be captured independently of application logging.
87	     */
88	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
89	
90	    private final ClinicService clinicService;
91	
