108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        rejectMissingOrBlankFields(ownerFieldsDto);
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        owner.setAddress(normalizeAddress(owner.getAddress()));
140	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
141	        owner.setEmail(normalizeEmail(owner.getEmail()));
142	        validatePostcode(owner.getPostcode(), owner.getCity());
143	        rejectFutureRegistrationDate(owner.getRegistrationDate());
144	        if (owner.getRegistrationDate() == null) {
145	            owner.setRegistrationDate(LocalDate.now());
146	        }
147	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
148	        rejectDailyLimitReached(owner.getRegistrationDate());
149	        rejectCityAtCapacity(owner.getCity());
150	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
151	            assignHousehold(owner);
152	        }
153	        rejectDuplicateIdentity(owner);
154	        assignPossibleDuplicate(owner);
155	        owner.setCustomerCode(generateCustomerCode(owner));
156	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
157	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
158	        this.clinicService.saveOwner(owner);
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
161	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
