248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
251	        Owner owner = this.clinicService.findOwnerById(ownerId);
252	        if (owner != null) {
253	            Pet pet = owner.getPet(petId);
254	            if (pet != null) {
255	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
256	            }
257	        }
258	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
