260	
261	    /**
262	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
263	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
264	     *
265	     * @param fields the submitted owner fields
266	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
267	     *                                        {@code null} or blank, or if address is blank after
268	     *                                        normalization
269	     */
270	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
271	        List<String> missing = new ArrayList<>();
272	        if (isBlank(fields.getFirstName())) {
273	            missing.add("firstName");
274	        }
275	        if (isBlank(fields.getLastName())) {
276	            missing.add("lastName");
277	        }
278	        if (isBlank(normalizeAddress(fields.getAddress()))) {
279	            missing.add("address");
280	        }
281	        if (isBlank(fields.getCity())) {
282	            missing.add("city");
283	        }
284	        if (isBlank(fields.getTelephone())) {
285	            missing.add("telephone");
286	        }
287	        if (!missing.isEmpty()) {
288	            throw new RequiredFieldsMissingException(missing);
289	        }
290	    }
291	
292	    private boolean isBlank(String value) {
293	        return value == null || value.isBlank();
294	    }
295	
296	    /**
297	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
298	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
299	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
300	     */
301	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
302	        "NSW", new int[] {2000, 2099},
303	        "VIC", new int[] {3000, 3099},
304	        "QLD", new int[] {4000, 4099});
305	
306	    /**
307	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
308	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
309	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
310	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
311	     *
312	     * @param postcode the submitted postcode, or {@code null} when omitted
313	     * @param city the owner's city, used to derive the region whose range constrains the postcode
314	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
315	     *                                  city's region
316	     */
317	    private void validatePostcode(String postcode, String city) {
318	        if (postcode == null) {
319	            return;
320	        }
321	        if (!postcode.matches("[0-9]{4}")) {
322	            throw new InvalidPostcodeException(postcode);
323	        }
324	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
325	        if (range == null) {
326	            return;
327	        }
328	        int value = Integer.parseInt(postcode);
329	        if (value < range[0] || value > range[1]) {
330	            throw new InvalidPostcodeException(postcode);
331	        }
332	    }
333	
334	    /**
335	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
336	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
337	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
338	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
339	     * <p>
340	     * Where a per-country rule is defined the national-number length is validated against the country
341	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
342	     * requires exactly 10.
343	     *
344	     * @param telephone the raw telephone value from the request
345	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
346	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
347	     */
348	    private String normalizeTelephone(String telephone) {
349	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
350	        String digits;
351	        if (cleaned.startsWith("+")) {
352	            digits = cleaned.substring(1);
353	        } else {
354	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
355	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
356	            digits = "61" + national;
357	        }
358	        if (!digits.matches("[0-9]{8,15}")) {
359	            throw new InvalidTelephoneException(cleaned);
360	        }
361	        // Validate the national-number length against the country code where a rule is defined.
362	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
363	            throw new InvalidTelephoneException(cleaned);
364	        }
365	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
366	            throw new InvalidTelephoneException(cleaned);
367	        }
368	        return "+" + digits;
369	    }
370	
371	    /**
372	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
373	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
374	     * lower-cased.
375	     *
376	     * @param email the raw email value from the request, or {@code null} if omitted
377	     * @return the lower-cased email, or {@code null} if none was supplied
378	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
379	     */
380	    private String normalizeEmail(String email) {
381	        if (email == null) {
382	            return null;
383	        }
384	        String trimmed = email.strip();
385	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
386	            throw new InvalidEmailException(email);
387	        }
388	        return trimmed.toLowerCase(Locale.ROOT);
389	    }
390	
391	    /**
392	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
393	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
394	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
395	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
396	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
397	     *
398	     * @param address the raw address value from the request (may be {@code null})
399	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
400	     */
401	    private String normalizeAddress(String address) {
402	        if (address == null) {
403	            return "";
404	        }
405	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
406	        if (collapsed.isEmpty()) {
407	            return "";
408	        }
409	        String[] tokens = collapsed.split(" ");
410	        StringBuilder sb = new StringBuilder(collapsed.length());
411	        for (int i = 0; i < tokens.length; i++) {
412	            if (i > 0) {
413	                sb.append(' ');
414	            }
415	            sb.append(expandAddressAbbreviation(tokens[i]));
416	        }
417	        return sb.toString();
418	    }
419	
420	    /**
421	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
422	     * returns the token unchanged when it is not a recognised abbreviation.
423	     *
424	     * @param token an upper-cased whole-word address token
425	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
426	     */
427	    private String expandAddressAbbreviation(String token) {
428	        return switch (token) {
429	            case "ST" -> "STREET";
430	            case "RD" -> "ROAD";
431	            case "AVE" -> "AVENUE";
432	            default -> token;
433	        };
434	    }
435	
436	    /**
437	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
438	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
439	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
440	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
441	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
442	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
443	     * sequence number is assigned.
444	     *
445	     * @param owner the owner being created, with normalized telephone and postcode already set
446	     * @return the assigned customer code
447	     */
448	    private String generateCustomerCode(Owner owner) {
449	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
450	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
451	            .substring(0, 8).toUpperCase(Locale.ROOT);
452	        return region + "-" + hash8;
453	    }
454	
455	    /**
456	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
457	     *
458	     * @param value the value to hash
459	     * @return the 64-character lower-case hex SHA-256 digest
460	     */
461	    private String sha256Hex(String value) {
462	        try {
463	            byte[] digest = MessageDigest.getInstance("SHA-256")
464	                .digest(value.getBytes(StandardCharsets.UTF_8));
465	            StringBuilder sb = new StringBuilder(digest.length * 2);
466	            for (byte b : digest) {
467	                sb.append(String.format("%02x", b));
468	            }
469	            return sb.toString();
470	        } catch (NoSuchAlgorithmException e) {
471	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
472	        }
473	    }
474	
475	    /**
476	     * Counts how many existing owners already share the given first name and last name, compared
477	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
478	     * owner being created.
479	     *
480	     * @param firstName the first name of the owner being created
481	     * @param lastName the last name of the owner being created
482	     * @return the number of existing owners with the same first and last name (case-insensitively)
483	     */
484	    private int countNamesakes(String firstName, String lastName) {
485	        return (int) this.clinicService.findAllOwners().stream()
486	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
487	                && lastName.equalsIgnoreCase(existing.getLastName()))
488	            .count();
489	    }
490	
491	    /**
492	     * The maximum number of owners permitted in a single city. A create request whose city already
493	     * holds this many owners is rejected.
494	     */
495	    private static final int CITY_OWNER_LIMIT = 50;
496	
497	    /**
498	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
499	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
500	     * differing only in the casing of their city share one capacity pool. The count is taken before the
501	     * new owner is persisted, so it excludes the owner being created.
502	     *
503	     * @param city the city of the owner being created
504	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
505	     */
506	    private void rejectCityAtCapacity(String city) {
507	        long existing = this.clinicService.findAllOwners().stream()
508	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
509	            .count();
510	        if (existing >= CITY_OWNER_LIMIT) {
511	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
512	        }
513	    }
514	
515	    /**
516	     * The maximum number of owners permitted to be created in a single day. A create request whose
517	     * registration date already holds this many owners is rejected.
518	     */
519	    private static final int DAILY_OWNER_LIMIT = 100;
520	
521	    /**
522	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
523	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
524	     * persisted, so it excludes the owner being created.
525	     *
526	     * @param registrationDate the registration date of the owner being created
527	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
528	     */
529	    /**
530	     * Adjusts an effective registration date so that it always falls on a business day. When the given
531	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
532	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
533	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
534	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
535	     * business-day-adjusted date.
536	     *
537	     * @param date the effective registration date, supplied or defaulted
538	     * @return the same date when it is a weekday, otherwise the next Monday
539	     */
540	    private LocalDate rollToBusinessDay(LocalDate date) {
541	        DayOfWeek day = date.getDayOfWeek();
542	        if (day == DayOfWeek.SATURDAY) {
543	            return date.plusDays(2);
544	        }
545	        if (day == DayOfWeek.SUNDAY) {
546	            return date.plusDays(1);
547	        }
548	        return date;
549	    }
550	
551	    /**
552	     * The number of owners that must already exist for a given day before a further create is flagged as a
553	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
554	     * the created owner carries {@code bulkSignupWarning = true}.
555	     */
556	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
557	
558	    /**
559	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
560	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
561	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
562	     * the daily create-limit rule's accumulation path.
563	     *
564	     * @param registrationDate the registration date of the owner being created
565	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
566	     */
567	    private boolean isBulkSignupDay(LocalDate registrationDate) {
568	        long existing = this.clinicService.findAllOwners().stream()
569	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
570	            .count();
571	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
572	    }
573	
574	    /**
575	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
576	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
577	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
578	     * made against the supplied value before any business-day adjustment.
579	     *
580	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
581	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
582	     */
583	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
584	        if (registrationDate == null) {
585	            return;
586	        }
587	        LocalDate today = LocalDate.now();
588	        if (registrationDate.isAfter(today)) {
589	            throw new FutureRegistrationDateException(registrationDate, today);
590	        }
591	    }
592	
593	    private void rejectDailyLimitReached(LocalDate registrationDate) {
594	        long existing = this.clinicService.findAllOwners().stream()
595	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
596	            .count();
597	        if (existing >= DAILY_OWNER_LIMIT) {
598	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
599	        }
600	    }
601	
602	    /**
603	     * Rejects a create request whose owner collides with an existing owner on the single derived
604	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
605	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
606	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
607	     * household (same {@code householdId}) with different telephones have different keys and are both
608	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} must already
609	     * have been assigned (when {@code sharesHousehold} was requested) before this check runs, so the key
610	     * compared here is the same one that is later returned.
611	     *
612	     * @param owner the owner being created, with normalized fields and any shared {@code householdId} set
613	     * @throws DuplicateIdentityException if an existing owner has the same identity key
614	     */
615	    private void rejectDuplicateIdentity(Owner owner) {
616	        String key = identityKey(owner);
617	        boolean taken = this.clinicService.findAllOwners().stream()
618	            .anyMatch(existing -> key.equals(identityKey(existing)));
619	        if (taken) {
620	            throw new DuplicateIdentityException(key);
621	        }
622	    }
623	
624	    /**
625	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
626	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
627	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
628	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
629	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
630	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
631	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
632	     *
633	     * @param owner the owner being created, with normalized telephone and validated postcode already set
634	     */
635	    private void assignPossibleDuplicate(Owner owner) {
636	        Integer matchId = null;
637	        if (owner.getPostcode() != null) {
638	            matchId = this.clinicService.findAllOwners().stream()
639	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
640	                    && owner.getPostcode().equals(existing.getPostcode())
641	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
642	                .map(Owner::getId)
643	                .filter(id -> id != null)
644	                .min(Comparator.naturalOrder())
645	                .orElse(null);
646	        }
647	        owner.setPossibleDuplicate(matchId != null);
648	        owner.setPossibleDuplicateOf(matchId);
649	    }
650	
651	    private boolean telephonesEqual(String a, String b) {
652	        return a == null ? b == null : a.equals(b);
653	    }
654	
655	    /**
656	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
657	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
658	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
659	     * Telephone and email are stored already normalized, so the stored values are used directly.
660	     *
661	     * @param owner the owner whose identity key is being derived
662	     * @return the owner's identity key
663	     */
664	    private String identityKey(Owner owner) {
665	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
666	        String email = owner.getEmail() == null ? "" : owner.getEmail();
667	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
668	        return telephone + "|" + email + "|" + householdId;
669	    }
670	
671	    /**
672	     * Assigns the owner being created into a shared household. When at least one existing owner has the
673	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
674	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
675	     * reused when present; otherwise a deterministic id derived from the household's last name and address
676	     * is minted, so independently created members of the same household converge on one value. When no
677	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
678	     *
679	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
680	     */
681	    private void assignHousehold(Owner owner) {
682	        String normalizedLastName = normalizeForComparison(owner.getLastName());
683	        String normalizedAddress = normalizeForComparison(owner.getAddress());
684	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
685	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
686	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
687	            .toList();
688	        if (housemates.isEmpty()) {
689	            return;
690	        }
691	        String householdId = housemates.stream()
692	            .map(Owner::getHouseholdId)
693	            .filter(id -> id != null && !id.isBlank())
694	            .findFirst()
695	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
696	        owner.setHouseholdId(householdId);
697	        for (Owner housemate : housemates) {
698	            if (!householdId.equals(housemate.getHouseholdId())) {
699	                housemate.setHouseholdId(householdId);
700	                this.clinicService.saveOwner(housemate);
701	            }
702	        }
703	    }
704	
705	    /**
706	     * Derives a stable household identifier from the normalized last name and address of a household, as
707	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
708	     * deterministic, so any owner independently joining the same household computes the same identifier.
709	     *
710	     * @param normalizedLastName the household's last name, already normalized for comparison
711	     * @param normalizedAddress the household's address, already normalized for comparison
712	     * @return a stable, shareable household identifier
713	     */
714	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
715	        String key = normalizedLastName + "|" + normalizedAddress;
716	        return sha256Hex(key).substring(0, 16);
717	    }
718	
719	    /**
720	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
721	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
722	     * lower-cased.
723	     *
724	     * @param value the raw value to normalize (may be {@code null})
725	     * @return the normalized value, or an empty string when {@code value} is {@code null}
726	     */
727	    private String normalizeForComparison(String value) {
728	        if (value == null) {
729	            return "";
730	        }
731	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
732	    }
733	}
